INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Outcome Ownership', 0, 'Finishes work end-to-end, follows up without reminders, owns mistakes.', '["Commitment met %", "Carry-over issues", "Post-release follow-ups"]'::jsonb, '["Needs reminders to finish committed work", "Delivers most commitments; some follow-up gaps", "Delivers committed work end-to-end and follows up after release", "Owns results beyond own tickets; closes gaps proactively", "Owns the business result; closes gaps nobody assigned"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Moral & Ethics', 1, 'Honest reporting, data privacy, responsible AI use.', '["360 ratings only — never scored from tool data"]'::jsonb, '["Status updates not reliable", "Mostly transparent; occasionally hides slips", "Honest status, credits others, follows policy", "Raises risks and mistakes early, protects data", "Raises uncomfortable truths early; a model of integrity"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Decision Making', 2, 'Timely, data-based decisions with clear reasoning.', '["ADRs / design docs authored", "Time blocked \"waiting for decision\""]'::jsonb, '["Avoids or delays decisions", "Decides with prompting", "Makes timely decisions within role, with reasoning", "Frames options and trade-offs, documents them", "Decisions hold up; others adopt their framing"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Problem Solving', 3, 'Finds root causes, not quick patches.', '["Root-cause fixes (no reopen)", "RCA documents"]'::jsonb, '["Patches symptoms", "Solves well-defined problems", "Breaks problems down and fixes root cause", "Solves ambiguous, cross-component problems", "Solves problems others were stuck on; shares the method"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Risk Appetite', 4, 'Proposes and owns new ideas, experiments responsibly.', '["Spikes / experiments run", "Risks logged in planning"]'::jsonb, '["Avoids anything new", "Tries new things only when asked", "Tries new approaches with a fallback plan", "Runs experiments; flags risks early in planning", "Takes calculated bets that move the product"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Adaptability', 5, 'Learns new tools and processes (including AI) and applies them.', '["Mid-sprint scope absorbed", "New areas picked up"]'::jsonb, '["Struggles with changed priorities", "Adjusts slowly to change", "Adjusts to priority changes without losing quality", "Picks up new domains quickly", "Helps the team re-plan and keeps morale during change"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Agility in Execution', 6, 'Delivers fast WITH quality.', '["Stale ratio", "Median PR size", "Cycle time"]'::jsonb, '["Work stalls without follow-up", "Moves work forward irregularly", "Moves work daily, small increments", "Ships small and often, unblocks others", "Sets the team pace; removes delivery friction"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Collaboration', 7, 'Helps others, shares knowledge.', '["Reviews given", "Kudos received", "Cross-team issues"]'::jsonb, '["Works in isolation", "Helps when asked", "Shares context, reviews others, responsive", "Builds bridges across teams", "Others seek them out; multiplies the team"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Resilience', 8, 'Steady performance under pressure, recovers from setbacks.', '["Incident participation", "Quality in Over sprints"]'::jsonb, '["Effectiveness drops under pressure", "Recovers slowly after setbacks", "Stays effective under pressure and after setbacks", "Steady during incidents and crunch", "Steadies the whole team through hard periods"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Resourcefulness', 9, 'Achieves results with limited resources, uses AI smartly.', '["Internal tools / scripts shared", "Docs written"]'::jsonb, '["Blocked without ideal tools", "Finds workarounds with help", "Finds a way with available tools and people", "Builds reusable tools / docs", "Creates assets that save the whole team time"]'::jsonb) ON CONFLICT (name) DO NOTHING;
INSERT INTO culture_values (name, ord, description, signals, anchors) VALUES ('Discipline', 10, 'Keeps Jira/tasks updated daily and accurately, follows agreed processes, raises delays early.', 'null'::jsonb, '["Below 50% daily updates — manager must chase for updates", "50–69% daily updates, frequent stale tickets, dates changed after deadline", "70–84% daily updates, some stale tickets, sometimes updates dates late", "85–94% daily updates, rare stale tickets, mostly proactive", "95%+ daily updates, no stale tickets, always re-plans before the due date"]'::jsonb) ON CONFLICT (name) DO NOTHING;
